/**
 * scripts/data/month3-dictionary.json  →  src/data/month3.ts
 *
 * The JSON is the verbatim transcription of the client's Month-3 document and is
 * the source of truth; this file is generated and must never be hand-edited.
 * Regenerate with: node scripts/gen-month3-data.mjs
 */
import { readFileSync, writeFileSync } from "node:fs";

const dict = JSON.parse(readFileSync("scripts/data/month3-dictionary.json", "utf8"));
const OFFSET = dict.platformDayOffset; // document day 1 = platform day 41

// The four weeks the client's Resumen defines: D1-D5, D6-D10, D11-D15, D16-D20.
// (The Diccionario grouped 5 weeks of 4; the client ruled the Resumen wins.)
const weekOf = (docDay) => Math.ceil(docDay / 5);

/** Emoji per topic — the day's own subject, so the game skin reinforces content. */
const TOPIC_EMOJI = {
  "Mi infancia": "🧸",
  "Mi familia": "👨‍👩‍👧",
  "Mi país": "🗺️",
  "Mis estudios": "🎓",
  "Mi experiencia laboral": "💼",
  "Mis viajes": "✈️",
  "Mis sueños": "🌠",
  "Mis objetivos": "🎯",
  "Mis emociones": "💗",
  "Una experiencia importante": "🔥",
};

const days = dict.days.map((d) => ({
  platformDay: d.day + OFFSET,
  docDay: d.day,
  week: weekOf(d.day),
  theme: d.theme,
  emoji: TOPIC_EMOJI[d.theme] ?? "🇫🇷",
  grammar: d.grammar,
  objective: d.objective,
  vocabulary: d.vocabulary.map((v) => ({
    fr: v.fr,
    es: v.es,
    example: v.example,
    exampleEs: v.exampleEs,
  })),
}));

const body = `// AUTO-GENERATED by scripts/gen-month3-data.mjs from
// scripts/data/month3-dictionary.json (the verbatim transcription of the
// client's "LIBERTÉ — MES 3: JE M'EXPRIME" dictionary + resumen).
// To change content, edit the JSON and regenerate. Do NOT hand-edit this file.
//
// Weeks follow the client's Resumen: 4 weeks of 5 days (D1-D5, D6-D10,
// D11-D15, D16-D20). The Diccionario's 5-weeks-of-4 grouping was ruled out by
// the client.

export type Month3Word = {
  fr: string;
  es: string;
  /** The document's own useful phrase for THIS word — phrase N teaches word N. */
  example: string;
  exampleEs: string;
};

export type Month3Day = {
  /** Day number in the platform (41-60). */
  platformDay: number;
  /** Day number in the client's document (1-20). */
  docDay: number;
  week: number;
  theme: string;
  emoji: string;
  grammar: string;
  objective: string;
  vocabulary: Month3Word[];
};

export const MONTH3_FIRST_DAY = ${OFFSET + 1};
export const MONTH3_LAST_DAY = ${OFFSET + 20};

/** True for the days the Month-3 arcade games are wired to. */
export function isMonth3(dayId: number | string): boolean {
  const n = Number(dayId);
  return Number.isFinite(n) && n >= MONTH3_FIRST_DAY && n <= MONTH3_LAST_DAY;
}

export const MONTH3: Record<string, Month3Day> = ${JSON.stringify(
  Object.fromEntries(days.map((d) => [String(d.platformDay), d])),
  null,
  2,
)};

export function month3Day(dayId: number | string): Month3Day | null {
  return MONTH3[String(dayId)] ?? null;
}
`;

writeFileSync("src/data/month3.ts", body);
console.log(
  `src/data/month3.ts — ${days.length} days (platform ${days[0].platformDay}-${days[days.length - 1].platformDay}), ` +
    `${days.reduce((a, d) => a + d.vocabulary.length, 0)} words`,
);
